#include &lt;stdio.h&gt;

using eGroup = enum {
    MAX_GRP = 0,
    CAP,
    RESIDUAL,
    MAX_VAL,
};

template &lt;typename T&gt;
auto _MIN(T a, T b)
{
    return (a &lt; b) ? a : b;
}

template &lt;typename T&gt;
auto _MAX(T a, T b)
{
    return (a &gt; b) ? a : b;
}

int main(void)
{
    int t;
    scanf("%d", &t);
    for(int tc = 1; tc &lt;= t; ++tc)
    {
        int n;
        int a[1'001];
        int max_v = -1;
        scanf("%d", &n);

        for(int i = 0; i &lt; n; ++i)
        {
            scanf("%d", &a[i]);
            max_v = _MAX(max_v, a[i]);
        }
        a[n] = 0;

        int ans = 987654321;
        int cap_val = -1;
        int D[1'001][MAX_VAL] = {0, 0, 0};
        for(int i = 0; i &lt;= n; ++i)
        {
            cap_val = a[i];

            D[0][MAX_GRP] = 0;
            if(a[0] &lt;= cap_val)
            {
                D[0][CAP] = 0;
            }
            else
            {
                D[0][CAP] = 987654321;
            }
            D[0][RESIDUAL] = a[0];
            for(int j = 1; j &lt; n; ++j)
            {
                D[j][MAX_GRP] = _MIN(D[j - 1][CAP], D[j - 1][RESIDUAL]);
                if(a[j] &lt;= cap_val)
                {
                    D[j][CAP] = _MIN(D[j - 1][MAX_GRP], D[j - 1][RESIDUAL]);
                }
                else
                {
                    D[j][CAP] = 987654321;
                }
                D[j][RESIDUAL] = _MIN(D[j - 1][MAX_GRP], D[j - 1][CAP]);
                D[j][RESIDUAL] = _MAX(D[j][RESIDUAL], a[j]);
            }

            ans = _MIN(ans, max_v + cap_val + D[n - 1][MAX_GRP]);
            ans = _MIN(ans, max_v + cap_val + D[n - 1][CAP]);
            ans = _MIN(ans, max_v + cap_val + D[n - 1][RESIDUAL]);
        }

        printf("#%d %d\n", tc, ans);
    }
}

