#include &lt;stdio.h&gt;
using ull = unsigned long long int;
const ull MOD = 1'000'000'007;

ull prev_DP[100];
ull curr_DP[100];
ull fact[1'000'001];

ull power(ull b, ull e, ull m) {
    ull r = 1;
    b %= m;
    for (; e &gt; 0; e &gt;&gt;= 1) {
        if (e & 1) { r = r * b % m; }
        b = b * b % m;
    }
    return r;
}

int main(void)
{
    fact[0] = 1;
    for (int i = 1; i &lt;= 1'000'000; ++i) {
        fact[i] = fact[i-1] * i % MOD;
    }

    int t;
    scanf("%d", &t);
    while (t--) {
        ull n, k;
        scanf("%llu %llu", &n, &k);

        for (int i = 0; i &lt; k; ++i) {
            prev_DP[i] = curr_DP[i] = 0;
        }
        prev_DP[0] = 1;

        ull steps = (n &lt; k) ? n : k;
        for (ull step = 2; step &lt;= steps; ++step) {
            for (int i = 0; i &lt; k; ++i) {
                curr_DP[i] = 0;
            }
            int wsize = (int)step;  // step &lt;= k 보장
            for (int r = 0; r &lt; k; ++r) {
                for (int p = 0; p &lt; wsize; ++p) {
                    int idx = ((r - p) % (int)k + (int)k) % (int)k;
                    curr_DP[r] = (curr_DP[r] + prev_DP[idx]) % MOD;
                }
            }
            for (int i = 0; i &lt; k; ++i) {
                prev_DP[i] = curr_DP[i];
            }
        }

        // 나머지 단계 (steps+1 ~ N) 일괄 처리
        ull mult = fact[n] * power(fact[steps], MOD - 2, MOD) % MOD;
        for (int i = 0; i &lt; k; ++i) {
            printf("%llu ", prev_DP[i] * mult % MOD);
        }
        printf("\n");
    }
}

5.6 Indicator random variable 정의
다음 지시변수를 정의하자.
\[
X_{ij} = I\{A[j] \text{ falls in bucket } i\}
\]
즉,
\[
X_{ij} =
\begin{cases}
1 & \text{if } A[j] \text{가 bucket } i \text{에 들어가면}, \\
0 & \text{otherwise.}
\end{cases}
\]
그러면 bucket \(i\)의 원소 수는 \[
n_i = \sum_{j=0}^{n-1} X_{ij}
\] 이다.

